import{_ as a,o as s,c as e,a5 as d}from"./chunks/framework.CslsFoWx.js";const b=JSON.parse('{"title":"Clients & fidélité","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/06-customers-loyalty.md","filePath":"generated/modules/06-customers-loyalty.md","lastUpdated":null}'),n={name:"modules/06-customers-loyalty.md"};function i(r,t,o,p,l,c){return s(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="clients-fidelite" tabindex="-1">Clients &amp; fidélité <a class="header-anchor" href="#clients-fidelite" aria-label="Permalink to &quot;Clients &amp; fidélité&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 3 · <a href="/VendoraSystem-docs/specs/06-customers-loyalty">spécification complète</a></span></p><p>Fiches clients, identification en caisse, historique (lot 3.1), fidélité (3.3), ardoise avec règlements dans le Z (3.4), reçus digitaux et QR client signé (3.5), sur les cinq plateformes et hors ligne.</p><div class="kpis"><div><b>24</b><span>faites</span></div><div><b>4</b><span>partielles</span></div><div><b>1</b><span>à faire</span></div><div><b>0</b><span>bloquées</span></div></div><h2 id="fiche-client" tabindex="-1">Fiche client <a class="header-anchor" href="#fiche-client" aria-label="Permalink to &quot;Fiche client&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Création express en caisse</strong><br><span class="muted">Le caissier crée une fiche avec un nom et un téléphone sans quitter la vente en cours, en moins de 10 secondes.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CUST-01, RG-CUST-03</td><td>3.1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-clients">📷</a></td></tr><tr><td><strong>Téléphone unique par tenant</strong><br><span class="muted">Saisir un téléphone déjà connu propose la fiche existante au lieu d&#39;en créer une seconde.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-02</td><td>3.1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-clients">📷</a></td></tr><tr><td><strong>Liste et fiche client au back-office</strong><br><span class="muted">Le gérant recherche, crée, édite et exporte ses clients, avec leurs achats et leur dernier achat.<br><i>Page Clients (lot 3.1) avec solde de points, journal et ajustement (lot 3.3), ardoise et plafond (lot 3.4).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-01</td><td>3.1, 3.3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-clients">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-fidelite">📷</a></td></tr><tr><td><strong>Historique d&#39;achats</strong><br><span class="muted">Les ventes rattachées à un client forment son historique, en caisse et au back-office.<br><i>Client attaché jusqu&#39;à la finalisation (lot 3.1). Lot R7 : rattachement a posteriori depuis « Ventes de la session » sous PIN manager (RG-CUST-05), points de la vente crédités, une seule fois par vente, audit <code>SALE / CUSTOMER_ATTACHED</code> — Android et iOS.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-05</td><td>3.1, R7</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-clients">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r7-clients-rapports">📷</a></td></tr></tbody></table><h2 id="identification" tabindex="-1">Identification <a class="header-anchor" href="#identification" aria-label="Permalink to &quot;Identification&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Identification par téléphone</strong><br><span class="muted">Le caissier tape au moins 4 chiffres du téléphone et la fiche apparaît en moins de 300 ms depuis la base locale.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-04</td><td>3.1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-clients">📷</a></td></tr><tr><td><strong>QR code client signé</strong><br><span class="muted">Le client présente un QR signé par le tenant ; un QR forgé ou d&#39;un autre tenant est rejeté.<br><i>QR <code>pos://c/{id}.{signature}</code> signé HMAC par une clé du tenant diffusée aux caisses ; vérifié hors ligne à la douchette, à la caméra ou dans la recherche du client ; QR affiché en SVG dans la fiche du back-office ; rotation par l&#39;OWNER.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-04</td><td>3.5</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-recus">📷</a></td></tr><tr><td><strong>Carte physique à code-barres</strong><br><span class="muted">Le client est identifié par le scan de sa carte ; une fiche peut avoir plusieurs cartes, une carte une seule fiche.<br><i>Carte EAN-13 interne préfixe 29 attribuée au back-office, scannée en caisse (le client est attaché au lieu d&#39;un produit) ; impression des cartes restante.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-04</td><td>3.1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-clients">📷</a></td></tr><tr><td><strong>Identification au kiosque et en salle</strong><br><span class="muted">Le kiosque et le téléphone de salle identifient un client pour cumuler ses points, sans création ni crédit.<br><i>Phase 3 pour le téléphone de salle ; l&#39;app kiosque est en phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td></td><td></td><td></td></tr></tbody></table><h2 id="fidelite" tabindex="-1">Fidélité <a class="header-anchor" href="#fidelite" aria-label="Permalink to &quot;Fidélité&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Règle d&#39;accumulation des points</strong><br><span class="muted">Le propriétaire fixe le nombre de points par unité dépensée et leur périmètre (tenant ou magasin).<br><i>1 point par montant net payé configurable, arrondi inférieur, périmètre tenant ou magasin ; gain au comptoir. Parts d&#39;addition : pas de client à l&#39;encaissement de la part, mais le rattachement après la vente (lot R7) crédite leurs points.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-10</td><td>3.3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-fidelite">📷</a></td></tr><tr><td><strong>Paliers et récompenses</strong><br><span class="muted">Le propriétaire configure des paliers de points donnant une remise en valeur ou en pourcentage plafonnée.<br><i>Paliers en montant ou en pourcentage plafonné, publiés par l&#39;owner au back-office.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-11</td><td>3.3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-fidelite">📷</a></td></tr><tr><td><strong>Rachat de points en caisse</strong><br><span class="muted">Le caissier applique en un tap le rachat d&#39;un palier sous forme de remise LOYALTY, sans dépasser le solde ni le total.<br><i>Bandeau caisse en un tap : meilleur palier atteignable, remise LOYALTY liée à l&#39;écriture REDEEMED, refus si le solde ne suffit pas.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-12</td><td>0.x, 3.3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-fidelite">📷</a></td></tr><tr><td><strong>Expiration des points en FIFO</strong><br><span class="muted">Les points expirent après un nombre de mois configurable, les plus anciens étant consommés en premier.<br><i>Expiration FIFO par le serveur (job quotidien et bouton au back-office), idempotente, diffusée aux caisses.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-13</td><td>3.3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-fidelite">📷</a></td></tr><tr><td><strong>Solde dérivé et ajustement motivé</strong><br><span class="muted">Le solde de points est la somme des gains, rachats et expirations ; un ajustement exceptionnel passe par le PIN manager.<br><i>Solde = somme des écritures partout ; ajustement motivé au back-office (jamais de « set solde ») ; fusion : les écritures suivent la fiche canonique.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-14</td><td>3.3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-fidelite">📷</a></td></tr><tr><td><strong>Points sur le ticket</strong><br><span class="muted">Le ticket affiche les points gagnés, le nouveau solde et le prochain palier atteignable.<br><i>Ticket imprimé : points utilisés, gagnés, solde, prochain palier, texte de l&#39;owner ; écran de succès des deux apps.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CUST-15</td><td>3.3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-fidelite">📷</a></td></tr><tr><td><strong>Reprise des points au retour</strong><br><span class="muted">Un retour reprend les points gagnés sur les lignes retournées.<br><i>Retour avec ticket : reprise au prorata du montant retourné, plafonnée au gain d&#39;origine (écriture REVERSED).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CUST-16</td><td>3.3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-fidelite">📷</a></td></tr></tbody></table><h2 id="ardoise" tabindex="-1">Ardoise <a class="header-anchor" href="#ardoise" aria-label="Permalink to &quot;Ardoise&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Vente à crédit avec plafond</strong><br><span class="muted">Le caissier vend en CUSTOMER_CREDIT à un client identifié ; au-delà du plafond, le paiement exige un PIN manager et un motif.<br><i>Mode Ardoise en caisse (client obligatoire), plafond par client, déblocage ponctuel par PIN manager + motif ; pas sur une addition de restaurant.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-20, RG-CUST-21, RG-CUST-22</td><td>3.4</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-ardoise">📷</a></td></tr><tr><td><strong>Règlement d&#39;ardoise</strong><br><span class="muted">Le caissier encaisse un règlement partiel ou total dans la session courante, compté au Z comme CREDIT_PAYMENT.<br><i>Règlement partiel ou total, espèces ou carte, depuis le menu de la caisse ; ligne dédiée hors CA au X et au Z, espèces dans le théorique.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-23</td><td>3.4</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-ardoise">📷</a></td></tr><tr><td><strong>Solde d&#39;ardoise visible</strong><br><span class="muted">Le solde d&#39;ardoise apparaît dès l&#39;identification et, en option par magasin, sur le ticket.<br><i>Dû et plafond sous le client attaché, dans la feuille de paiement, la liste et la fiche client ; lot R7 : « Ardoise : reste dû » et plafond imprimés sur le ticket de vente (hors contenu scellé).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-24</td><td>3.4, R7</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-ardoise">📷</a></td></tr><tr><td><strong>Points différés sur crédit</strong><br><span class="muted">Une vente à crédit ne crédite ses points qu&#39;au prorata des règlements reçus.<br><i>La part à crédit ne rapporte pas de points à la vente ; le règlement crédite les points (critère 11).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-25</td><td>3.4</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-ardoise">📷</a></td></tr><tr><td><strong>Ardoises ouvertes et rappels</strong><br><span class="muted">Le gérant voit les ardoises par ancienneté et envoie des rappels si le client a consenti au canal.<br><i>Liste « Ardoises » avec ancienneté et filtre ; lot R7 : rappel par email, puis SMS et WhatsApp (lot R7 suite) — un bouton par canal accepté, envoi groupé par le canal préféré de chacun, jamais sans consentement (refus tracé), date du dernier rappel. Fournisseur SMS / WhatsApp réel : hors code.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-26</td><td>3.4, R7</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-ardoise">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r7-clients-rapports">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r7-suite-canaux-rapports">📷</a></td></tr><tr><td><strong>Dépassement de plafond après sync</strong><br><span class="muted">Deux ventes à crédit hors ligne dépassant le plafond sont conservées, le client est bloqué et le gérant alerté.<br><i>Plafond évalué hors ligne ; un dépassement après synchronisation est signalé (journal serveur, rouge au back-office), jamais annulé.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-52</td><td>3.4</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-ardoise">📷</a></td></tr><tr><td><strong>Avoir et crédit client au retour</strong><br><span class="muted">Un retour peut être remboursé en avoir sur le compte du client plutôt qu&#39;en espèces ou par le moyen d&#39;origine.<br><i>Lot R2 : « Avoir » proposé au retour quand un client est attaché, avec ou sans ticket ; aucune espèce ne sort ; « avoir X » sous le client, dans la feuille de paiement et au back-office ; utilisable en paiement.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td></td><td>3.4, R2</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-ardoise">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-r2-vente">📷</a></td></tr></tbody></table><h2 id="recus-digitaux" tabindex="-1">Reçus digitaux <a class="header-anchor" href="#recus-digitaux" aria-label="Permalink to &quot;Reçus digitaux&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Reçu en ligne par QR</strong><br><span class="muted">Chaque ticket porte un QR vers un reçu en ligne non devinable, aux couleurs du magasin, généré hors ligne.<br><i>Jeton de 64 caractères généré hors ligne, QR « Votre recu en ligne » sur le ticket, page /r/{jeton} servable à la synchronisation, aux couleurs résolues du magasin, sans aucune donnée client (noindex, no-store).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-30</td><td>3.5</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-recus">📷</a></td></tr><tr><td><strong>Envoi du reçu par email, SMS ou WhatsApp</strong><br><span class="muted">Le reçu part par le canal choisi si le client y a consenti et que l&#39;intégration est configurée.<br><i>EMAIL (lot 3.5) ; lot R7 suite : SMS et WhatsApp — un bouton par canal consenti avec sa coordonnée en caisse (Android, iOS) et au back-office, consentement du canal revérifié par le serveur, issue tracée. La messagerie fonctionne en mode simulé (DEV) ; reste hors code le fournisseur réel (opérateur SMS, WhatsApp Business : comptes et numéros expéditeurs) — en production les envois sont refusés et tracés tant qu&#39;il n&#39;est pas branché.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-31</td><td>3.5, R7</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-recus">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r7-suite-canaux-rapports">📷</a></td></tr><tr><td><strong>Consentements par canal</strong><br><span class="muted">Le consentement par canal est horodaté, rattaché à sa source et révocable à tout moment.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-32</td><td>3.1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-clients">📷</a></td></tr></tbody></table><h2 id="donnees-personnelles" tabindex="-1">Données personnelles <a class="header-anchor" href="#donnees-personnelles" aria-label="Permalink to &quot;Données personnelles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Anonymisation</strong><br><span class="muted">À la demande du client, le manager efface ses données personnelles sous PIN, l&#39;historique comptable restant intact.<br><i>Anonymisation irréversible (lot 3.1) ; refusée tant que l&#39;ardoise n&#39;est pas soldée ou passée en perte (lot 3.4) ; PIN en caisse restant.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-40, RG-CUST-41</td><td>3.1, 3.4</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-clients">📷</a></td></tr><tr><td><strong>Export des données d&#39;un client</strong><br><span class="muted">Le back-office exporte la fiche et l&#39;historique d&#39;un client ; aucune suppression pure n&#39;existe.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-42</td><td>3.1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-clients">📷</a></td></tr></tbody></table><h2 id="hors-ligne-doublons" tabindex="-1">Hors ligne &amp; doublons <a class="header-anchor" href="#hors-ligne-doublons" aria-label="Permalink to &quot;Hors ligne &amp; doublons&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Clients hors ligne</strong><br><span class="muted">Créer un client, l&#39;identifier, vendre à crédit et racheter des points fonctionnent sans internet.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CUST-50</td><td>3.1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-clients">📷</a></td></tr><tr><td><strong>Fusion des doublons</strong><br><span class="muted">Le serveur fusionne automatiquement deux fiches au même téléphone ; un doublon probable n&#39;est fusionné qu&#39;après validation manager.<br><i>Fusion AUTOMATIQUE par téléphone E.164 identique (lot 3.1). Lot R7 : doublons PROBABLES (même email, même nom à la casse, aux accents et aux espaces près, au moins deux mots) détectés à chaque création / modification et à la demande, page « Doublons clients », fusion validée par un manager (<code>CustomerMerged</code> MANUAL vers les caisses, ventes / points / ardoise / cartes réunis), « Pas un doublon » définitif. La détection est gardée côté serveur (pas d&#39;événement <code>CustomerDuplicateDetected</code> vers les appareils, qui n&#39;en ont pas l&#39;usage).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CUST-51</td><td>3.1, R7</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-clients">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r7-clients-rapports">📷</a></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Points sur les parts d&#39;addition et au kiosque ; ajustement sous PIN en caisse ; alerte de solde négatif après rachats simultanés.</li><li>Ardoise : rappels envoyés (SMS / WhatsApp / email selon consentement), solde sur le ticket imprimé, ardoise sur les additions.</li><li>Détection probabiliste des doublons et fusion manuelle validée par un manager.</li><li>Impression des cartes client ; identification en salle et au kiosque ; attacher un client à une addition.</li><li>Reçus : envoi par SMS et WhatsApp (intégrations spec 16), fournisseur SMTP réel, impression du QR client sur une carte.</li></ul>',20)])])}const g=a(n,[["render",i]]);export{b as __pageData,g as default};
